/* eslint-disable max-len */

'use strict';

// MODULES //

var addon = require( './../src/addon.node' );


// MAIN //

/**
* Generates a single-precision floating-point Vandermonde matrix.
*
* @param {NonNegativeInteger} M - number of rows in the matrix `Out`
* @param {NonNegativeInteger} N - number of columns in the matrix `Out`
* @param {number} mode - specifies whether columns should contain powers that are increasing (`1`) or decreasing (`-1`)
* @param {Float32Array} x - input vector
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Float32Array} out - output matrix
* @param {integer} strideOut1 - stride length for the first dimension of `Out`
* @param {integer} strideOut2 - stride length for the second dimension of `Out`
* @param {NonNegativeInteger} offsetOut - starting index for `Out`
* @returns {Float32Array} output matrix
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );
* var out = new Float32Array( 9 );
*
* svander( 3, 3, -1, x, 1, 0, out, 3, 1, 0 );
* // out => <Float32Array>[ 1.0, 1.0, 1.0, 4.0, 2.0, 1.0, 9.0, 3.0, 1.0 ]
*/
function svander( M, N, mode, x, strideX, offsetX, out, strideOut1, strideOut2, offsetOut ) {
	addon.ndarray( M, N, mode, x, strideX, offsetX, out, strideOut1, strideOut2, offsetOut );
	return out;
}


// EXPORTS //

module.exports = svander;
